import heapq

def match(orders):
    buy_heap = []  # max-heap by price via negation: (-price, arrival, id)
    sell_heap = []  # min-heap by price: (price, arrival, id)
    book = {}  # id -> dict(side, price, qty, arrival, status)
    trades = []

    for arrival, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book and book[oid]['status'] == 'active':
                book[oid]['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                p, arr, sid = sell_heap[0]
                info = book.get(sid)
                if info is None or info['status'] != 'active' or info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and p > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['status'] = 'filled'
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                             'arrival': arrival, 'status': 'active'}
                heapq.heappush(buy_heap, (-price, arrival, oid))
        else:  # sell
            while remaining > 0 and buy_heap:
                negp, arr, bid = buy_heap[0]
                p = -negp
                info = book.get(bid)
                if info is None or info['status'] != 'active' or info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and p < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['status'] = 'filled'
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                             'arrival': arrival, 'status': 'active'}
                heapq.heappush(sell_heap, (price, arrival, oid))

    return trades

